/* Read-only study view of the existing practice bank. No attempt storage access. */
const ExamStudy=(()=>{
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const questions=practiceSets.flatMap(s=>s.questions.map(q=>({...q,set:s,...examScope[q.id]})));
 let restorePrint=null;
 function render(main){
  if(!document.getElementById('study-controls')){
   main.innerHTML=`<a href="?mode=timed">← Timed practice and saved attempts</a><p class="eyebrow">ONE QUESTION BANK · TWO WAYS TO LEARN</p><h1>Study explained examples</h1><p class="lede">Attempt a question on paper, explain your reasoning, then reveal the guide and identify your next step.</p><p>60 original formative questions for Years 11 and 12. These are not official SCSA examination items or complete papers. Each criterion earns one practice mark; accept equivalent correct reasoning.</p><p class="notice">Study does not change saved attempts. Timers on unfinished timed attempts keep running. Answers are public learning resources; open a guide only when ready.</p><section id="study-controls" class="practice-setup" aria-label="Filter study questions"><label for="study-unit">Year and unit<select id="study-unit"><option value="all">All units</option>${[1,2,3,4].map(u=>`<option value="${u}">Year ${u<3?11:12} · Unit ${u}</option>`).join('')}</select></label><label for="study-type">Response type<select id="study-type"><option value="all">All response types</option><option>Short answer</option><option>Extended response</option></select></label><label for="study-query">Find a question<input id="study-query" type="search" placeholder="Try SQL, tracing or encryption"></label><button type="button" id="study-reset">Clear filters</button><div class="practice-actions"><button type="button" id="study-print">Print questions</button><button type="button" id="study-print-guides">Print with explained answers</button></div><p>Print uses the currently visible questions. Study notes are written on paper; this view does not save responses.</p></section><p id="study-count" role="status"></p><div id="study-bank">${questions.map(q=>`<article class="question-card study-card" id="study-${q.id}" tabindex="-1" data-unit="${q.unit}" data-type="${esc(q.type)}"><p class="eyebrow">YEAR ${q.set.year} · UNIT ${q.unit} · ${esc(q.type)} · ${q.criteria.length} MARKS</p><h2>${esc(q.title)}</h2><p>${esc(q.prompt)}</p>${q.code?`<pre tabindex="0" aria-label="Code example"><code>${esc(q.code)}</code></pre>`:''}<p class="scope">${q.mixed?'Includes support-booklet or additional implementation material. Check the scope guide and teach the relevant technique before assessment.':'Syllabus-linked practice: an original question, not an official examination item.'}</p><p>Attempt first. Predict the key points before opening the guide.</p><details><summary>Show explained answer and marking criteria</summary><h3>Example answer</h3><div class="model">${esc(q.model)}</div><h3>Why this earns credit</h3><ol>${q.criteria.map(c=>`<li>${esc(c)} (1 mark)</li>`).join('')}</ol><p><strong>Common mistake:</strong> ${esc(q.mistake)}</p><p>Compare with your original answer. Explain the first mismatch, close the guide and retry with a changed input or scenario.</p></details><p class="study-links"><a href="../#${q.chapter}">Revisit the chapter</a> · <a href="?mode=timed#${q.set.id}">Practice this set</a> · <a href="#study-${q.id}">Link to this question</a></p></article>`).join('')}</div><p class="footer">Original formative content CC BY 4.0 · code MIT. <a href="../licence.html">Reuse details</a></p>`;
   const params=new URLSearchParams(location.search);
   for(const [id,param] of [['study-unit','unit'],['study-type','type'],['study-query','q']]){const el=document.getElementById(id);if(params.has(param))el.value=params.get(param);if(!el.value&&id!=='study-query')el.value='all';el.addEventListener(id==='study-query'?'input':'change',()=>filter(true));}
   document.getElementById('study-reset').addEventListener('click',()=>{document.getElementById('study-unit').value='all';document.getElementById('study-type').value='all';document.getElementById('study-query').value='';filter(true);});
   for(const [id,guides] of [['study-print',false],['study-print-guides',true]])document.getElementById(id).addEventListener('click',()=>{
    const details=[...main.querySelectorAll('.study-card details')];const previous=details.map(d=>d.open);details.forEach(d=>d.open=guides);restorePrint=()=>{details.forEach((d,i)=>d.open=previous[i]);restorePrint=null;};try{window.print();}finally{restorePrint?.();}
   });
   filter(false);
  }
  const target=document.getElementById(location.hash.slice(1));
  if(target?.classList.contains('study-card')){document.getElementById('study-unit').value='all';document.getElementById('study-type').value='all';document.getElementById('study-query').value='';filter(false);target.focus();target.scrollIntoView();}
 }
 function filter(update){
  const unit=document.getElementById('study-unit').value,type=document.getElementById('study-type').value,query=document.getElementById('study-query').value.trim().toLowerCase();let count=0;
  for(const q of questions){const card=document.getElementById('study-'+q.id);card.hidden=(unit!=='all'&&String(q.unit)!==unit)||(type!=='all'&&q.type!==type)||!`${q.title} ${q.topic} ${q.prompt} ${q.code||''}`.toLowerCase().includes(query);if(!card.hidden)count++;}
  document.getElementById('study-count').textContent=count?`Showing ${count} of ${questions.length} questions.`:'No matching questions. Clear filters to see all examples.';
  if(update){const p=new URLSearchParams({mode:'study'});if(unit!=='all')p.set('unit',unit);if(type!=='all')p.set('type',type);if(query)p.set('q',query);history.replaceState(null,'','?'+p);}
 }
 window.addEventListener('afterprint',()=>restorePrint?.());
 return {render};
})();
